/**
 * WelcomeModal Component - Modern welcome modal with enhanced design
 */
import { __ } from '@wordpress/i18n';
import {
    Modal,
    Typography,
    Space,
    Button,
    Steps,
    Card,
    Row,
    Col,
    Divider
} from 'antd';
import {
    RocketOutlined,
    SettingOutlined,
    ThunderboltOutlined,
    CheckCircleOutlined,
    StarOutlined
} from '@ant-design/icons';

const { Title, Paragraph, Text } = Typography;
const { Step } = Steps;

const WelcomeModal = ({ isOpen, onClose, onDismiss }) => {
    const steps = [
        {
            title: __('Choose Builders', 'marqueex'),
            description: __('Select which page builders to integrate with', 'marqueex'),
            icon: <SettingOutlined />
        },
        {
            title: __('Optimize Performance', 'marqueex'),
            description: __('Configure performance settings for best results', 'marqueex'),
            icon: <ThunderboltOutlined />
        },
        {
            title: __('Test Compatibility', 'marqueex'),
            description: __('Ensure everything works with your theme', 'marqueex'),
            icon: <CheckCircleOutlined />
        }
    ];

    const features = [
        {
            icon: <RocketOutlined style={{ color: '#1890ff' }} />,
            title: __('Lightning Fast', 'marqueex'),
            description: __('Optimized for performance with lazy loading and caching')
        },
        {
            icon: <SettingOutlined style={{ color: '#52c41a' }} />,
            title: __('Easy Integration', 'marqueex'),
            description: __('Works seamlessly with popular page builders')
        },
        {
            icon: <StarOutlined style={{ color: '#faad14' }} />,
            title: __('Professional Design', 'marqueex'),
            description: __('Beautiful animations and modern UI components')
        }
    ];

    return (
      <Modal
        title={
          <Space>
            <RocketOutlined style={{ color: "#1890ff", fontSize: "20px" }} />
            <span style={{ fontSize: "18px", fontWeight: 600 }}>
              {__("Welcome to MarqueeX", "marqueex")}
            </span>
          </Space>
        }
        open={isOpen}
        onCancel={onClose}
        width={720}
        footer={
          <Space>
            <Button onClick={onDismiss}>
              {__("Don't show again", "marqueex")}
            </Button>
            <Button type="primary" onClick={onDismiss}>
              {__("Get Started", "marqueex")}
            </Button>
          </Space>
        }
        centered
      >
        <Space direction="vertical" size="large" style={{ width: "100%" }}>
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <Title level={3} style={{ marginBottom: 8, color: "#1890ff" }}>
              {__("Create Amazing Marquee Effects", "marqueex")}
            </Title>
            <Paragraph
              style={{ fontSize: "16px", color: "#666", marginBottom: 0 }}
            >
              {__(
                "Transform your website with stunning scrolling text, news tickers, and infinite sliders. Configure your settings below to get started.",
                "marqueex"
              )}
            </Paragraph>
          </div>

          <Row gutter={[16, 16]}>
            {features.map((feature, index) => (
              <Col span={8} key={index}>
                <Card
                  size="small"
                  style={{
                    textAlign: "center",
                    height: "120px",
                    background: "#fafafa",
                    border: "1px solid #f0f0f0",
                  }}
                >
                  <Space direction="vertical" size="small">
                    <div style={{ fontSize: "24px" }}>{feature.icon}</div>
                    <Text strong style={{ fontSize: "13px" }}>
                      {feature.title}
                    </Text>
                    <Text type="secondary" style={{ fontSize: "11px" }}>
                      {feature.description}
                    </Text>
                  </Space>
                </Card>
              </Col>
            ))}
          </Row>

          <Divider />

          <div>
            <Title level={4} style={{ marginBottom: 16, textAlign: "center" }}>
              {__("Quick Setup Guide", "marqueex")}
            </Title>
            <Steps direction="vertical" size="small" current={-1}>
              {steps.map((step, index) => (
                <Step
                  key={index}
                  title={step.title}
                  description={step.description}
                  icon={step.icon}
                />
              ))}
            </Steps>
          </div>
        </Space>
      </Modal>
    );
};

export default WelcomeModal;
